import{_ as e,o as a,c as d,a5 as r}from"./chunks/framework.DbSlGjul.js";const g=JSON.parse('{"title":"Terminology","description":"","frontmatter":{},"headers":[],"relativePath":"reference/terminology.md","filePath":"reference/terminology.md","lastUpdated":1789820328000}'),o={name:"reference/terminology.md"};function n(i,t,s,l,c,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h1><p>Use the task names from Table 2 of the HiveBoard paper in instructions, figures, result tables, and interfaces. The table below maps those names to the identifiers used in trial records.</p><h2 id="task-names-and-identifiers" tabindex="-1">Task names and identifiers <a class="header-anchor" href="#task-names-and-identifiers" aria-label="Permalink to &quot;Task names and identifiers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task name</th><th>Trial identifier (<code>attachment_id</code>)</th><th>Category</th></tr></thead><tbody><tr><td>Ball valve</td><td><code>valve_ball</code></td><td>Torque</td></tr><tr><td>Ball valve + ring</td><td><code>valve_ball_ring</code></td><td>Torque</td></tr><tr><td>Gate valve (small)</td><td><code>valve_gate_small</code></td><td>Torque</td></tr><tr><td>Gate valve (large)</td><td><code>valve_gate_large</code></td><td>Torque</td></tr><tr><td>Circuit breaker</td><td><code>circuit_breaker</code></td><td>Torque</td></tr><tr><td>Light bulb</td><td><code>light_bulb</code></td><td>Precision</td></tr><tr><td>Thread (M8)</td><td><code>thread_m8</code></td><td>Precision</td></tr><tr><td>Thread (M30)</td><td><code>thread_m30</code></td><td>Precision</td></tr><tr><td>Peg insertion</td><td><code>peg_insertion</code></td><td>Precision</td></tr><tr><td>Button</td><td><code>button</code></td><td>Composed assembly</td></tr><tr><td>Lock and key</td><td><code>lock</code></td><td>Composed assembly</td></tr><tr><td>Drawer</td><td><code>drawer</code></td><td>Composed assembly</td></tr><tr><td>Shock absorber</td><td><code>shock_absorber</code></td><td>Composed assembly</td></tr></tbody></table><p>HiveBoard has 12 attachment designs evaluated in 13 conditions. The ball valve is evaluated without and with a friction ring, giving two conditions for the same attachment design. Ball valve + ring is the condition with the ring fitted. Record five trials for each of the 13 conditions, including separate blocks for Ball valve and Ball valve + ring.</p><p>The category headings are <strong>Torque-based tasks</strong>, <strong>Precision-based tasks</strong>, and <strong>Composed assembly tasks</strong>. In tables, use <strong>Torque</strong>, <strong>Precision</strong>, and <strong>Composed assembly</strong>. The abbreviation “Assembly” in existing templates and the paper&#39;s Table 2 refers to Composed assembly.</p><h2 id="hardware-tasks-and-evaluation" tabindex="-1">Hardware, tasks, and evaluation <a class="header-anchor" href="#hardware-tasks-and-evaluation" aria-label="Permalink to &quot;Hardware, tasks, and evaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Honeycomb base</td><td>The structure into which the attachments are mounted.</td></tr><tr><td>Attachment</td><td>A physical mechanism mounted on the base, such as the drawer or a gate valve.</td></tr><tr><td>Task</td><td>The operation performed on an attachment, with a specified starting state and success criterion.</td></tr><tr><td>Condition</td><td>A scored task configuration. The two ball-valve configurations are separate conditions.</td></tr><tr><td>Trial</td><td>One recorded execution of a task, ending at success, failure, timeout, or a safety stop.</td></tr><tr><td>Platform</td><td>The end-effector and the system that positions and commands it.</td></tr><tr><td>End-effector</td><td>The gripper, hand, or other terminal device that interacts with the attachment.</td></tr><tr><td>Control interface</td><td>The interface used to command the platform. Record the control mode or policy separately where relevant.</td></tr><tr><td>Asset</td><td>A digital file or model, such as CAD geometry, a mesh, URDF, or USD. Use “attachment” for the physical mechanism.</td></tr><tr><td>Attempt</td><td>A discrete approach to the task within a trial; count from 1. Abandoning an approach and starting another adds one attempt.</td></tr><tr><td>Regrasp</td><td>A release followed by grasping the part again; count from 0. An initial grasp is not a regrasp.</td></tr><tr><td>Last completed stage</td><td>The highest completed stage of a composed assembly task, recorded as <code>stage_reached</code>; 0 means no stage was completed.</td></tr><tr><td>Dominant failure cause</td><td>The single cause recorded in <code>failure_cause</code> for an unsuccessful trial.</td></tr></tbody></table><h2 id="existing-names-in-files" tabindex="-1">Existing names in files <a class="header-anchor" href="#existing-names-in-files" aria-label="Permalink to &quot;Existing names in files&quot;">​</a></h2><p>Older labels and file paths may use the names below. They refer to the same attachments; descriptive details such as the button cover or the threaded peg remain part of the task instructions.</p><table tabindex="0"><thead><tr><th>Existing label or filename term</th><th>Task name</th></tr></thead><tbody><tr><td>Ball valve with friction ring</td><td>Ball valve + ring</td></tr><tr><td>Small gate valve; Valve Gate (Small)</td><td>Gate valve (small)</td></tr><tr><td>Large gate valve; Valve Gate (Large)</td><td>Gate valve (large)</td></tr><tr><td>Light bulb socket; light bulb and socket; <code>Lamp/</code></td><td>Light bulb</td></tr><tr><td>M8 threaded fastener; Thread M8</td><td>Thread (M8)</td></tr><tr><td>M30 threaded fastener; Thread M30</td><td>Thread (M30)</td></tr><tr><td>Threaded peg insertion; Peg Insertion Plate</td><td>Peg insertion</td></tr><tr><td>Covered button; Hidden Push Button</td><td>Button</td></tr><tr><td><code>Key/</code></td><td>Lock and key</td></tr><tr><td>Sliding Drawer; <code>box</code> in image/video filenames</td><td>Drawer</td></tr><tr><td><code>spring</code> in image/video filenames</td><td>Shock absorber</td></tr></tbody></table><p>Keep existing identifiers, paths, and data fields unchanged. For example, <code>lock</code> remains the trial identifier for Lock and key, <code>light_bulb</code> remains the identifier for Light bulb, and <code>control_method</code> remains the runner&#39;s stored field for the control interface. The CSV outcome <code>fail</code> is displayed as “Failure” in the runner.</p><p>Thread (M14) is available in the 3D viewer but is not one of the 13 scored conditions.</p><p>See <a href="/hivedocs/benchmark/tasks">How to perform each task</a> for operating instructions and <a href="/hivedocs/benchmark/logging">Trial logging</a> for counting conventions.</p>',14)])])}const f=e(o,[["render",n]]);export{g as __pageData,f as default};
